editorialMd:
Build values

`head` is the first node of a linked list. A node holds a number in val and a link to the next node in next. Follow next until there are no more nodes. Record each val in order. The list has no loops. An empty list gives an empty `values`.

Return the answer

Add only the numbers in `values` that are greater than 0. Store the sum in `positiveTotal`. Complete `chainInspectionPositiveInkInvoice` so it returns `positiveTotal`. Return it, do not print it.

Why this works

Each value in `values` follows task 1. The later tasks use only those values. Keeping these steps separate helps avoid returning the list when the question asks for one number. Check empty input, one item, repeated values, and the largest allowed input.

Efficiency goal: time O(n); extra memory, including the helper list, O(n). n is the number of nodes. These labels describe how work and memory grow with the input.

javascript
function chainInspectionPositiveInkInvoice(head) {
  const a=head; let out=[];
  for(let node=a;node;node=node.next)out.push(node.val);
  return out.reduce((s,x)=>s+Math.max(0,x),0);
}


typescript
type ListNode = { val: number; next: ListNode | null };
function chainInspectionPositiveInkInvoice(head: ListNode | null): number {
  const a=head; let out:number[]=[];
  for(let node=a;node;node=node.next)out.push(node.val);
  return out.reduce((s,x)=>s+Math.max(0,x),0);
}


python
def chainInspectionPositiveInkInvoice(head):
    a=head
    out=[]
    node=a
    while node:
        out.append(node.val)
        node=node.next
    return sum(x for x in out if x>0)


java
class Solution {
  public int chainInspectionPositiveInkInvoice(ListNode head) {
    ListNode a=head; List<Integer> out=new ArrayList<>();
    {for(ListNode node=a;node!=null;node=node.next)out.add(node.val);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
